var i=`0386-poffertjes`;var n=`world-0386`;var s=`NL`;var r=`western-europe`;var o=8;var a=72;var l={en:`Poffertjes`,ua:`Поферт'єс`};var u={en:`A traditional Netherlands dish made with all-purpose flour, whole cow milk, chicken egg, instant yeast. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Нідерланди. Основні інгредієнти: пшеничне борошно універсальне, цільне коров'яче молоко, куряче яйце, інстантні дріжджі. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var h=[{en:`Whisk the listed batter ingredients until smooth. Let the mixture rest briefly so the flour hydrates.`,ua:`Збийте складники рідкого тіста до однорідності. Дайте суміші коротко відпочити, щоб борошно увібрало вологу.`,t:[`mixing`,`whisking`],m:10,i:[[`all-purpose-flour`,260,`g`],[`whole-cow-milk`,360,`ml`],[`chicken-egg`,2,`pcs`],[`instant-yeast`,5,`g`],[`white-granulated-sugar`,30,`g`],[`table-salt`,3,`g`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 45 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 45 хвилин.`,t:[`rapid-chilling`],m:45,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 15 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 15 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:15,i:[[`unsalted-butter`,80,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,70,`g`]]}];var d={slug:i,id:n,country:`NL`,region:r,servings:8,minutes:72,title:l,text:u,steps:h};export{s as country,d as default,n as id,a as minutes,r as region,o as servings,i as slug,h as steps,u as text,l as title};